begin;
update public.dining_tables set status='fechada' where status='aberta';
update public.cash_sessions set status='CLOSED' where status='OPEN';
do $$begin perform set_config('request.jwt.claim.sub',(select id::text from auth.users where lower(email)='dejandrea@gmail.com'),true);end $$;
set local role authenticated;
do $$
declare acc uuid;cat uuid:=gen_random_uuid();cash uuid:=gen_random_uuid();pix uuid:=gen_random_uuid();session uuid:=gen_random_uuid();pdv uuid:=gen_random_uuid();other uuid:=gen_random_uuid();dest uuid:=gen_random_uuid();registered jsonb;product uuid;stock uuid;line uuid;payload jsonb;answer jsonb;c public.dining_tables;sale public.cash_sales;reopened uuid;close_request uuid:=gen_random_uuid();
begin
 select id into acc from public.financial_accounts where caixa_padrao;
 perform public.finance_config('categories',cat,'{"nome":"POS fixture revenue","natureza":"INCOME","ativo":true}');
 perform public.finance_config('methods',cash,'{"nome":"POS fixture cash","tipo":"CASH","ativo":true,"usar_pdv":true,"prazo_dias":0,"max_parcelas":1}');
 perform public.finance_config('methods',pix,'{"nome":"POS fixture pix","tipo":"PIX","ativo":true,"usar_pdv":true,"prazo_dias":0,"max_parcelas":1}');
 perform public.cash_operation(session,'OPEN',jsonb_build_object('conta_id',acc,'categoria_id',cat,'valor_abertura',0));
 registered:=public.save_registered_item(gen_random_uuid(),null,null,'{"produto":true,"insumo":true,"product":{"nome":"POS fixture product","unidade":"UN","preco_venda":10,"custo":2},"stock":{},"components":[],"suppliers":[]}');
 product:=(registered->'product'->>'id')::uuid;stock:=(registered->'stock'->>'id')::uuid;
 perform public.comanda_operation(pdv,'OPEN_PDV','{"identificacao":"Venda avulsa","customer_codigo":null}');
 perform public.comanda_operation(pdv,'ADD_PRODUCT',jsonb_build_object('request_id',gen_random_uuid(),'total',0,'paid_total',0,'product_id',product,'quantidade',3));
 select * into c from public.dining_tables where id=pdv;
 select id into line from public.dining_table_items where codigo_mesa=c.codigo_mesa;
 payload:=jsonb_build_object('request_id',gen_random_uuid(),'total',30,'paid_total',0,'item_id',line,'expected_quantity',3,'quantidade',4);
 perform public.comanda_operation(pdv,'CHANGE_QUANTITY',payload);perform public.comanda_operation(pdv,'CHANGE_QUANTITY',payload);
 if (select quantidade from public.dining_table_items where id=line)<>4 or (select product_id from public.dining_table_items where id=line)<>product or (select total_geral from public.dining_tables where id=pdv)<>40 then raise exception 'Quick quantity changed product or duplicated';end if;
 begin perform public.comanda_operation(pdv,'CHANGE_QUANTITY',payload||jsonb_build_object('request_id',gen_random_uuid(),'total',40));raise exception 'FAIL stale item quantity accepted';exception when raise_exception then if SQLERRM like 'FAIL%' then raise;end if;end;
 perform public.comanda_operation(pdv,'PAY',jsonb_build_object('request_id',gen_random_uuid(),'total',40,'paid_total',0,'mode','ITEMS','items',jsonb_build_array(jsonb_build_object('item_id',line,'quantidade',2)),'payments',jsonb_build_array(jsonb_build_object('forma_id',pix,'valor',20))));
 begin perform public.comanda_operation(pdv,'CHANGE_QUANTITY',jsonb_build_object('request_id',gen_random_uuid(),'total',40,'paid_total',20,'item_id',line,'expected_quantity',4,'quantidade',1));raise exception 'FAIL paid quantity removed';exception when raise_exception then if SQLERRM like 'FAIL%' then raise;end if;end;
 perform public.comanda_operation(pdv,'CHANGE_QUANTITY',jsonb_build_object('request_id',gen_random_uuid(),'total',40,'paid_total',20,'item_id',line,'expected_quantity',4,'quantidade',3));
 payload:=jsonb_build_object('request_id',gen_random_uuid(),'total',30,'paid_total',20,'discount_amount',5,'surcharge_amount',2,'expected_discount',0,'expected_surcharge',0);
 perform public.comanda_operation(pdv,'SET_ADJUSTMENTS',payload);perform public.comanda_operation(pdv,'SET_ADJUSTMENTS',payload);
 if (select total_geral from public.dining_tables where id=pdv)<>27 then raise exception 'Adjusted total incorrect';end if;
 begin perform public.comanda_operation(pdv,'SET_ADJUSTMENTS',payload||jsonb_build_object('request_id',gen_random_uuid(),'total',27,'expected_discount',5,'expected_surcharge',2,'discount_amount',30,'surcharge_amount',0));raise exception 'FAIL discount below paid amount accepted';exception when raise_exception then if SQLERRM like 'FAIL%' then raise;end if;end;
 begin perform public.comanda_operation(pdv,'SET_ADJUSTMENTS',payload||jsonb_build_object('request_id',gen_random_uuid(),'total',27,'expected_discount',5,'expected_surcharge',2,'discount_amount',0.001));raise exception 'FAIL fractional sale cent accepted';exception when raise_exception then if SQLERRM like 'FAIL%' then raise;end if;end;
 insert into public.dining_table_items(codigo_mesa,descricao,valor_unitario,quantidade) values(c.codigo_mesa,'POS fixture avulso',5,2);
 if (select total_geral from public.dining_tables where id=pdv)<>37 then raise exception 'Item recalculation dropped adjustments';end if;
 perform public.comanda_operation(pdv,'CHANGE_QUANTITY',jsonb_build_object('request_id',gen_random_uuid(),'total',37,'paid_total',20,'item_id',line,'expected_quantity',3,'quantidade',4));
 perform public.comanda_operation(dest,'OPEN','{"identificacao":"POS fixture destination"}');
 begin perform public.comanda_operation(pdv,'TRANSFER',jsonb_build_object('request_id',gen_random_uuid(),'total',47,'paid_total',20,'destination_id',dest,'destination_total',0,'destination_paid_total',0,'items',jsonb_build_array(jsonb_build_object('item_id',line,'quantidade',1))));raise exception 'FAIL adjusted items transferred without reconciliation';exception when raise_exception then if SQLERRM like 'FAIL%' then raise;end if;end;
 payload:=jsonb_build_object('request_id',close_request,'total',47,'paid_total',20,'payments',jsonb_build_array(jsonb_build_object('forma_id',cash,'valor',27,'recebido',50)));
 begin perform public.comanda_operation(pdv,'CLOSE',payload||jsonb_build_object('payments',jsonb_build_array(jsonb_build_object('forma_id',cash,'valor',27,'recebido',26))));raise exception 'FAIL insufficient cash accepted';exception when raise_exception then if SQLERRM like 'FAIL%' then raise;end if;end;
 answer:=public.comanda_operation(pdv,'CLOSE',payload);perform public.comanda_operation(pdv,'CLOSE',payload);
 select * into sale from public.cash_sales where id=(answer->>'sale_id')::uuid;
 if sale.total<>47 or sale.discount_amount<>5 or sale.surcharge_amount<>2 then raise exception 'Sale did not preserve adjustments';end if;
 if not exists(select 1 from public.comanda_payments p join public.comanda_closures cc on cc.id=p.closure_id where cc.comanda_id=pdv and p.tipo_forma='CASH' and p.valor=27 and p.received_amount=50 and p.change_amount=23) then raise exception 'Cash tender or change snapshot missing';end if;
 if (select (value->>'expected_cash')::numeric from jsonb_array_elements(public.cash_dashboard()) where value->>'id'=session::text)<>27 or (select saldo from public.stock_items where id=stock)<>-4 then raise exception 'Cash net value or product stock incorrect';end if;
 answer:=public.cash_sale_operation(sale.id,'REOPEN',jsonb_build_object('request_id',gen_random_uuid(),'motivo','POS fixture reopen'));
 reopened:=(answer->>'comanda_id_aberta')::uuid;
 select * into c from public.dining_tables where id=reopened;
 if c.total_geral<>47 or c.discount_amount<>5 or c.surcharge_amount<>2 or c.sale_record<>sale.number or (select (value->>'expected_cash')::numeric from jsonb_array_elements(public.cash_dashboard()) where value->>'id'=session::text)<>0 then raise exception 'Reopening lost adjusted total or net refund';end if;
 if (select saldo from public.stock_items where id=stock)<>0 then raise exception 'Reopening did not restore stock';end if;
 perform public.comanda_operation(reopened,'CLOSE',jsonb_build_object('request_id',gen_random_uuid(),'total',47,'paid_total',0,'payments',jsonb_build_array(jsonb_build_object('forma_id',cash,'valor',47,'recebido',50))));
 if (select total from public.cash_sales where id=sale.id)<>47 or (select (value->>'expected_cash')::numeric from jsonb_array_elements(public.cash_dashboard()) where value->>'id'=session::text)<>47 then raise exception 'Reclosed sale incorrect';end if;
 perform public.comanda_operation(other,'OPEN_PDV','{"identificacao":"POS fixture conversion"}');
 perform public.comanda_operation(other,'ADD_PRODUCT',jsonb_build_object('request_id',gen_random_uuid(),'total',0,'paid_total',0,'product_id',product,'quantidade',1));
 perform public.comanda_operation(other,'SET_ADJUSTMENTS',jsonb_build_object('request_id',gen_random_uuid(),'total',10,'paid_total',0,'discount_amount',1,'surcharge_amount',0,'expected_discount',0,'expected_surcharge',0));
 perform public.comanda_operation(other,'CONVERT',jsonb_build_object('request_id',gen_random_uuid(),'total',9,'paid_total',0,'identificacao','POS fixture comanda'));
 if not exists(select 1 from public.dining_tables where id=other and origem='COMANDA' and total_geral=9 and discount_amount=1) then raise exception 'Conversion lost adjustment';end if;
end $$;
reset role;
do $$begin
 if has_column_privilege('authenticated','public.dining_tables','discount_amount','UPDATE') or has_column_privilege('authenticated','public.comanda_payments','received_amount','INSERT') then raise exception 'New sale fields directly writable';end if;
end $$;
rollback;
